/*
 * A370119  Numbers whose arithmetic derivative is a multiple of 9.
 * https://oeis.org/A370119
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th smallest integer k such that the arithmetic
 *            derivative k' is a multiple of 9.
 *            (0,1,14,27,50,54,65,68,77,81,86,108,122,135,155,158,160,162,189,194,196,203,208,212,
 *            …) The sequence is generated by a greedy search
 * Range:     u8 n <= 27, u16 n <= 66, u32 n <= 66, u64 n <= 66, u128 n <= 66,
 *            big any n
 * Helpers:   derivative_mod9_uint64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/derivative_mod9_uint64.h"

/* Global cache for generated values.  */
static seq_t *cache = NULL;
static size_t cache_len = 0;     /* number of cached terms */
static size_t cache_cap = 0;     /* allocated capacity */
static uint64_t next_candidate = 2;  /* next integer to test (after 1) */

/* Grow the cache array if needed.  */
static void grow_cache(void)
{
    if (cache_cap == 0) {
        cache_cap = 16;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    } else {
        cache_cap *= 2;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }
}

/* Ensure that cache contains at least n terms.  */
static void ensure_cache(size_t n)
{
    if (n <= cache_len) return;

    /* Initialise cache with the first two terms 0 and 1.  */
    if (cache_len == 0) {
        grow_cache();
        cache[0] = 0;
        cache_len = 1;
    }
    if (cache_len == 1) {
        if (cache_cap < 2) grow_cache();
        cache[1] = 1;
        cache_len = 2;
    }

    while (cache_len < n) {
        uint64_t cand = next_candidate;
        ++next_candidate;

        if (derivative_mod9_uint64(cand) == 0) {
            if (cache_len == cache_cap) grow_cache();
            cache[cache_len++] = (seq_t)cand;
        }
    }
}

seq_t a(idx_t n)
{
    /* The sequence is 1‑indexed: a(1) = 0, a(2) = 1, ... */
    if (n < 1) return 0;          /* out of range, can be treated as 0 */
    size_t idx = (size_t)n;
    ensure_cache(idx);
    return cache[idx - 1];
}
